namespace ForgeScope.Hub;

public static partial class Views
{
    static void Welcome(Page p)
    {
        p.Body.Append($"""
        <section class="welcome"><div class="eyebrow">FORGESCOPE</div>
        <h1>{p.T("Understand the problem. Choose your next step.", "Entenda o problema. Saiba por onde começar.", "Entiende el problema. Elige el siguiente paso.")}</h1>
        <p class="muted">{p.T("Connect a repository, upload a project or paste code. Review findings, source locations and next checks in one dashboard.", "Conecte um repositório, envie um projeto ou cole código. Veja os achados, as localizações e as próximas verificações em um único painel.", "Conecta un repositorio, sube un proyecto o pega código. Revisa los hallazgos, las ubicaciones y las siguientes comprobaciones en un panel.")}</p>
        <div class="actions"><a class="button primary" href="#start">{p.T("Start analysis", "Começar análise", "Iniciar análisis")}</a><a class="button" href="#demo">{p.T("See how it works", "Ver como funciona", "Ver cómo funciona")}</a></div></section>
        """);
    }
    static void SourceForms(Page p)
    {
        p.Body.Append($"""
        <section id="start"><h2>{p.T("What would you like to analyze?", "O que você quer analisar?", "¿Qué quieres analizar?")}</h2>
        <p>{p.T("Choose a source. Your results stay private to your account.", "Escolha uma origem. Os resultados ficam privados na sua conta.", "Elige un origen. Los resultados son privados para tu cuenta.")}</p>
        <div class="source-options"><article class="card"><span class="badge">GitHub</span><h3>{p.T("Your repositories", "Seus repositórios", "Tus repositorios")}</h3><p>{p.T("Choose a repository to investigate changes or monitor failed executions.", "Escolha um repositório para investigar mudanças ou acompanhar execuções com falha.", "Elige un repositorio para investigar cambios o seguir ejecuciones fallidas.")}</p><a class="button" href="/repositories?lang={p.Lang}">{p.T("Choose repository", "Escolher repositório", "Elegir repositorio")}</a></article>
        <article class="card"><span class="badge">ZIP</span><h3>{p.T("Upload your project folder", "Envie a pasta do projeto", "Sube la carpeta del proyecto")}</h3><p>{p.T("Compress your source folder as a .zip file and upload it here.", "Compacte a pasta do código em um arquivo .zip e envie aqui.", "Comprime la carpeta del código en un archivo .zip y súbelo aquí.")}</p>
        <form method="post" action="/source" enctype="multipart/form-data">{p.Hidden()}<label>{p.T("Project ZIP", "ZIP do projeto", "ZIP del proyecto")}<input type="file" name="archive" accept=".zip,application/zip" required></label><button class="primary">{p.T("Analyze ZIP", "Analisar ZIP", "Analizar ZIP")}</button></form>
        <p class="upload-note">{p.T("Up to 3 MB compressed, 10 MB extracted and 250 files. Remove secrets and generated folders before uploading.", "Até 3 MB compactados, 10 MB extraídos e 250 arquivos. Remova segredos e pastas geradas antes do envio.", "Hasta 3 MB comprimidos, 10 MB extraídos y 250 archivos. Elimina secretos y carpetas generadas antes de subir.")}</p></article></div>
        <article class="card"><h3>{p.T("Or paste your code", "Ou cole seu código", "O pega tu código")}</h3>
        <form method="post" action="/source">{p.Hidden()}<label>{p.T("File name with extension", "Nome do arquivo com extensão", "Nombre del archivo con extensión")}<input name="filename" placeholder="src/example.py" maxlength="200" required></label><label>{p.T("Source code", "Código-fonte", "Código fuente")}<textarea name="code" rows="8" maxlength="200000" required spellcheck="false"></textarea></label><button class="primary">{p.T("Analyze code", "Analisar código", "Analizar código")}</button></form></article>
        <p class="upload-note">{p.T("Source files are processed temporarily and deleted after analysis. Findings may contain code excerpts. No project code, builds or tests are executed. General repository checks work across languages; semantic dependency analysis currently covers Java and C#.", "Os arquivos são processados temporariamente e excluídos após a análise. Os achados podem conter trechos de código. O projeto, builds e testes não são executados. As verificações gerais atendem várias linguagens; a análise semântica de dependências cobre Java e C# atualmente.", "Los archivos se procesan temporalmente y se eliminan después del análisis. Los hallazgos pueden contener fragmentos de código. No se ejecutan el proyecto, builds ni pruebas. Las comprobaciones generales cubren varios lenguajes; el análisis semántico de dependencias cubre Java y C# actualmente.")}</p></section>
        """);
    }
    static void Tour(Page p)
    {
        p.Body.Append($"""
        <section id="demo" class="card"><span class="badge">{p.T("Guided demonstration · example data", "Demonstração guiada · dados de exemplo", "Demostración guiada · datos de ejemplo")}</span><h2>{p.T("From input to a clear result", "Do envio ao resultado claro", "Del envío al resultado claro")}</h2><p>{p.T("Expand each step to follow an example. This demonstration does not scan your repositories.", "Abra cada etapa para acompanhar um exemplo. Esta demonstração não analisa seus repositórios.", "Abre cada paso para seguir un ejemplo. Esta demostración no analiza tus repositorios.")}</p>
        <details class="tour-step" open><summary>01 · {p.T("Choose your input", "Escolha o que enviar", "Elige la entrada")}</summary><p>{p.T("Select a GitHub repository, attach project.zip, or paste code with its file name. No commit SHA is needed for local files.", "Selecione um repositório GitHub, anexe projeto.zip ou cole código com o nome do arquivo. Arquivos locais não exigem SHA de commit.", "Selecciona un repositorio GitHub, adjunta proyecto.zip o pega código con su nombre. Los archivos locales no requieren SHA de commit.")}</p><a href="#start">{p.T("Go to import", "Ir para importação", "Ir a importación")}</a></details>
        <details class="tour-step"><summary>02 · {p.T("Read the result in the dashboard", "Leia o resultado no painel", "Lee el resultado en el panel")}</summary><div class="demo-result"><strong>{p.T("Example: dependency download blocked", "Exemplo: download de dependência bloqueado", "Ejemplo: descarga de dependencia bloqueada")}</strong><p><code>Dependency download HTTP 429</code></p><p>{p.T("The remote service rejected requests because a rate limit was reached. This points to the dependency download step, not a confirmed source-code bug.", "O serviço remoto recusou requisições por limite de acesso. Isso aponta para a etapa de download de dependências, sem comprovar um bug no código.", "El servicio remoto rechazó solicitudes por un límite de acceso. Esto apunta a la descarga de dependencias, sin confirmar un fallo en el código.")}</p></div></details>
        <details class="tour-step"><summary>03 · {p.T("Review evidence and next checks", "Confira a evidência e o próximo passo", "Revisa la evidencia y el siguiente paso")}</summary><p>{p.T("For this example: inspect retry/backoff and dependency caching. File and line appear only when supplied by a meaningful source diagnostic. Review every proposed change before applying it.", "Neste exemplo: confira novas tentativas com espera e o cache de dependências. Arquivo e linha aparecem apenas quando informados por um diagnóstico de código pertinente. Revise qualquer alteração antes de aplicar.", "En este ejemplo: revisa reintentos con espera y caché de dependencias. Archivo y línea aparecen cuando un diagnóstico de código pertinente los proporciona. Revisa los cambios antes de aplicarlos.")}</p></details></section>
        """);
    }
}
